#!/usr/bin/env node
import { readFileSync, writeFileSync } from 'node:fs';
import { dirname, join } from 'node:path';
import { fileURLToPath } from 'node:url';

const here = dirname(fileURLToPath(import.meta.url));
const root = join(here, '..', '..');
const en = JSON.parse(readFileSync(join(root, 'locales', 'en.json'), 'utf8'));
const vi = JSON.parse(readFileSync(join(root, 'locales', 'vi.json'), 'utf8'));
const out = `// GENERATED by scripts/i18n/build-locales-bundle.mjs — do not edit by hand.
// Source of truth: locales/en.json + locales/vi.json. Run \`npm run i18n:bundle\`.
window.__tbotLocales = ${JSON.stringify({ en, vi }, null, 2)};
`;
writeFileSync(join(root, 'locales', 'bundle.js'), out);
console.log('Wrote locales/bundle.js');
